body {
    margin: 0;
    font-family: 'Arial', sans-serif;
    background: #1e1e1e;
    color: #fff;
}

.sidebar {
    position: fixed;
    width: 250px;
    height: 100%;
    background: #000000;
    transition: width 0.3s;
}

.sidebar .logo {
    padding: 15px;
    text-align: center;
    background: #000000;
    color: #C7FF6D;
    font-size: 24px;
    font-weight: bold;
    border-bottom: 1px solid #444;
}

.sidebar ul {
    list-style: none;
    padding: 0;
    margin: 0;
}

.sidebar ul li {
    border-bottom: 1px solid #444;
}

.sidebar ul li a {
    text-decoration: none;
    color: #C7FF6D;
    display: block;
    padding: 15px;
    transition: background 0.3s;
}

.sidebar ul li a:hover {
    background: #444;
}

.content {
    margin-left: 250px;
    padding: 20px;
    background: url('background.jpg') no-repeat center center fixed;
    background-size: cover;
}

.content h1 {
    font-size: 36px;
    font-family: 'Courier New', Courier, monospace;
    color: #C7FF6D;
}

.content p {
    font-size: 18px;
}

form {
    background: rgba(0, 0, 0, 0.5);
    padding: 20px;
    border-radius: 10px;
}

input[type="text"], input[type="email"], input[type="password"], textarea {
    width: 100%;
    padding: 10px;
    margin: 10px 0;
    border: 1px solid #444;
    border-radius: 5px;
    background: #333;
    color: #fff;
}

input[type="submit"] {
    background: #C7FF6D;
    border: none;
    padding: 10px 20px;
    border-radius: 5px;
    cursor: pointer;
    color: #111;
}

input[type="submit"]:hover {
    background: #9dd543;
}

p {
    animation-duration: 3s;
    animation-name: slidein;
  }
  
  @keyframes slidein {
    from {
      margin-left: 100%;
      width: 300%;
    }
  
    to {
      margin-left: 0%;
      width: 100%;
    }
  }
